// Call is side-effect free and safe to call repeatedly.
unsigned int v = obs_websocket_get_api_version();
// Record observed version for potential gating in later stubs (diagnostic only).
FUZZ_SET_ATTR_INT_GLOBAL("obsws_api_version", (int)v);
// No outputs; nothing else to enforce here.

// request_type must be non-null, non-empty C string. Prefer a known valid name when fuzz string is empty.
std::string req = FUZZ_PARAM_STR();
if (req.empty()) { req = "GetVersion"; }
const char *request_type = req.c_str();

// request_data may be NULL; we pass NULL to avoid constructing obs_data_t here.
obs_data_t *request_data = nullptr;

// Perform the call; may return NULL if handler unavailable.
obs_websocket_request_response *response = obs_websocket_call_request(request_type, request_data);

// For the harness, we require a non-null response before handing it to the pool.
if (!response) { FUZZ_BAIL(); }

// Provide response as an output so another stub (response_free) can release it.
// Note: The response owns its internal strings; do not dereference after free.

// Release resources associated with a response previously returned by obs_websocket_call_request.
// API is safe with NULL, but the harness guarantees non-null inputs; call directly.
obs_websocket_request_response_free(response);
// Do not return the response; it is no longer valid.

// Build a non-capturing lambda convertible to the required C function pointer type.
obs_websocket_event_callback_function cb = +[](uint64_t ts, const char *vendor, const char *name, void *priv) {
    // Minimal, fast callback body; do not block or allocate.
    (void)ts; (void)vendor; (void)name; (void)priv;
};

// Use the evt_cb helper object address as stable priv_data to ensure we can later unregister.
void *priv = (void *)evt_cb;

// Attempt to register; false indicates registration failed (e.g., plugin unavailable).
bool ok = obs_websocket_register_event_callback(cb, priv);

// Track registration state and the exact identity needed for unregistration.
FUZZ_SET_ATTR_PTR(evt_cb, "cb_ptr", (void *)cb);
FUZZ_SET_ATTR_PTR(evt_cb, "priv_ptr", priv);
FUZZ_SET_ATTR_INT(evt_cb, "registered", ok ? 1 : 0);

// Return the helper object so it can be reused by the unregister stub.

// Enforce that we only attempt unregistration for a callback we previously registered.
int registered = FUZZ_GET_ATTR_INT(evt_cb, "registered");
void *cb_ptr = FUZZ_GET_ATTR_PTR(evt_cb, "cb_ptr");
void *priv_ptr = FUZZ_GET_ATTR_PTR(evt_cb, "priv_ptr");
if (!registered || !cb_ptr || !priv_ptr) { FUZZ_BAIL(); }

// Reconstruct the function pointer and priv_data and attempt unregistration.
obs_websocket_event_callback_function cb = (obs_websocket_event_callback_function)cb_ptr;
void *priv = priv_ptr;

bool ok = obs_websocket_unregister_event_callback(cb, priv);
// If unregistration failed, bail to avoid drifting state.
if (!ok) { FUZZ_BAIL(); }

// Mark as unregistered so repeated attempts bail fast.
FUZZ_SET_ATTR_INT(evt_cb, "registered", 0);
// Keep the helper object in the pool for potential re-registration later.

// Construct a helper object to manage registration/unregistration of an event callback.
// Although this struct is described as a transient helper, we heap-allocate it for the fuzzing pool.
obs_websocket_event_callback *evt_cb = new (std::nothrow) obs_websocket_event_callback();
if (!evt_cb) { FUZZ_BAIL(); }

// Provide a minimal, non-blocking callback function that matches the required signature.
obs_websocket_event_callback_function cb = +[](uint64_t ts, const char *vendor, const char *name, void *priv) {
    // Keep callback work trivial and fast; do not allocate or block.
    (void)ts; (void)vendor; (void)name; (void)priv;
};

// Initialize fields. Use the object pointer as a stable priv_data default.
evt_cb->callback = cb;
evt_cb->priv_data = (void *)evt_cb;

// Initialize tracking attributes for later register/unregister endpoints.
FUZZ_SET_ATTR_INT(evt_cb, "registered", 0);
FUZZ_SET_ATTR_PTR(evt_cb, "cb_ptr", (void *)cb);      // identity used by register/unregister stubs
FUZZ_SET_ATTR_PTR(evt_cb, "priv_ptr", nullptr);       // will be set on successful registration

